records.command:
$ErrorActionPreference='Stop'
if (Get-LocalUser | Where-Object Name -EQ 'book2_ch03') {
 throw 'Test account name already exists'
}
$secret=ConvertTo-SecureString 'Book2-Lab-Only!2026' -AsPlainText -Force
$created=$null
$added=$false
try {
 $created=New-LocalUser -Name 'book2_ch03' -Password $secret -Disabled -Description 'Book chapter03 temporary lab'
 $created | Format-List Name,Enabled,SID
 Add-LocalGroupMember -SID 'S-1-5-32-544' -Member $created
 $added=$true
 Get-LocalGroupMember -SID 'S-1-5-32-544' | Format-List Name,SID
} finally {
 if ($added) { Remove-LocalGroupMember -SID 'S-1-5-32-544' -Member $created }
 if ($created) { Remove-LocalUser -SID $created.SID }
 $secret.Dispose()
}
Get-LocalUser | Where-Object Name -EQ 'book2_ch03' | Format-List Name,SID
Get-LocalGroupMember -SID 'S-1-5-32-544' | Format-List Name,SID
